import{_ as e,c as a,a2 as p,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第一百四十章 恒河中泥沙的数量","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/140第一百四十章 恒河中泥沙的数量.md","filePath":"meditation/巴利文大藏经/140第一百四十章 恒河中泥沙的数量.md"}'),_={name:"meditation/巴利文大藏经/140第一百四十章 恒河中泥沙的数量.md"};function r(n,t,i,s,d,c){return o(),a("div",null,t[0]||(t[0]=[p('<h1 id="第一百四十章-恒河中泥沙的数量" tabindex="-1">第一百四十章 恒河中泥沙的数量 <a class="header-anchor" href="#第一百四十章-恒河中泥沙的数量" aria-label="Permalink to &quot;第一百四十章 恒河中泥沙的数量&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部15相应8经/恒河经(无始相应/因缘篇/如来记说)</p><p>有个时候，佛陀住在王舍城栗鼠饲养处的竹林中，有一天，有一个婆罗门来到佛陀的住所，他与佛陀互相问候后，就在一旁坐下，那个婆罗门对佛陀说：“乔达摩，到现在为止，已经过去多少劫（劫解释，见第一百三十七章）了？有多少劫已经过去了？”</p><p>佛陀说：“婆罗门！已经过去很多劫了，过去劫的多少很难用数量来描述，也就是说过去劫的多少很难用像几劫、几百劫、几千劫、几十万劫这样的时间长度来估算。过去劫的数量应该是无量的，应该是无法估算出来的。”</p><p>这个婆罗门说：“乔达摩，你能为我说个比喻吗？让我能够明白过去劫数量的多少。”</p><p>佛陀说：“婆罗门，说比喻还是可以的，婆罗门就如同这条流向大海的恒河一样，恒河里到底有多少粒河沙，到底有多少粒泥沙，那是很难数清楚的，当然也很难用像几粒、几百粒、几千粒、几十万粒这样的计数单位来测量清楚恒河里总共有多少粒河沙、泥沙。婆罗门，同样的道理，过去劫的数量也非常的多，也很难用像几劫、几百劫、几千劫、几十万劫这样的时间长度来估算。这是为什么呢？婆罗门，因为生死轮回是永无止境的，是无穷无尽的！所以过去的劫也是永无止境、无穷无尽的。这些不明白世间的真相、规则，被无知障碍，被贪爱束缚捆绑的众生，他们的生死轮回也是循环不止的，也是无穷无尽的，他们也是无法知道他们自己生死轮回的起点在什么地方的。</p><p>婆罗门，你无数次的生死轮回，无数次的承受痛苦，无数次的经历不幸，无数次的忧愁、悲伤、苦闷、忧虑、绝望。无数次的死后埋入墓地。婆罗门，你要从世间解脱出来，要从生死轮回中解脱出来，就不要再挂念和执着世间一切的事物，就不要再执着和挂念自己一切的行为、言语、念想。这样你就不会被世间一切的事物束缚捆绑，这样你就不会被自己的行为、言语、念想束缚捆绑。这样你就能最终从生死轮回中永远的解脱出来。”</p><p>这个婆罗门听完佛陀说法后，激动的对佛陀说：“大德，您说的太好了，您对我说的这个法就如同在黑暗中点亮了一盏明灯，让我能够看见周围的事物，大德，请让我皈依您，请让我皈依您的法，请让我皈依您的僧团，我愿意从今天开始就成为您的在家修行弟子，我愿意从今天开始终生都受持您制定的戒律，终生都按您所说的正法去修行。”</p><p>佛陀接受了这个婆罗门的皈依，这个婆罗门感激的顶礼佛陀，随喜赞叹佛陀说法的无量功德，并按着佛陀所说的法去修行。</p>',10)]))}const f=e(_,[["render",r]]);export{m as __pageData,f as default};
